const assert = require("node:assert/strict");
const fs = require("node:fs");
const source = fs.readFileSync("apps/worker/src/jobs/diagnostics/DiagnosticWorkerOwnershipBatch.e2e.spec.ts", "utf8");
const guard = source.match(/if \(app\.hostname !==[\s\S]*?\) throw new Error\("Separate task database and restricted caller required; ownership7 stays preserved"\);/);
assert.ok(guard, "Expected fixture guard must exist");
const reject = new Function("app", "privileged", "process", `${guard[0]}\nreturn false;`);
const worker = "postgresql://restricted@127.0.0.1:61149/r6c_batch_seam";
const owner = "postgresql://owner@127.0.0.1:61149/r6c_batch_seam";
function allowed(workerUrl, ownerUrl, env) {
  try { return !reject(new URL(workerUrl), new URL(ownerUrl), { env }); }
  catch (error) {
    assert.equal(error.message, "Separate task database and restricted caller required; ownership7 stays preserved");
    return false;
  }
}
const checks = [
  ["configured PostgreSQL port 61149", worker, owner, process.env, true],
  ["default PostgreSQL port 65379", worker.replace(":61149/", ":65379/"), owner.replace(":61149/", ":65379/"), {}, true],
  ["unset port rejects 61149", worker, owner, {}, false],
  ["configured port rejects 65379", worker.replace(":61149/", ":65379/"), owner.replace(":61149/", ":65379/"), process.env, false],
  ["loopback hostname remains exact", worker.replace("127.0.0.1", "localhost"), owner.replace("127.0.0.1", "localhost"), process.env, false],
  ["database prefix remains exact", worker.replace("r6c_batch_seam", "other_seam"), owner.replace("r6c_batch_seam", "other_seam"), process.env, false],
  ["privileged host must match", worker, owner.replace(":61149/", ":61150/"), process.env, false],
  ["privileged database must match", worker, owner.replace("r6c_batch_seam", "r6c_batch_other"), process.env, false],
  ["caller usernames must differ", worker, owner.replace("owner@", "restricted@"), process.env, false],
];
let failures = 0;
for (const [label, workerUrl, ownerUrl, env, expected] of checks) {
  const actual = allowed(workerUrl, ownerUrl, env);
  console.log(`${actual === expected ? "PASS" : "FAIL"}: ${label}; expected=${expected}, actual=${actual}`);
  if (actual !== expected) failures++;
}
console.log(`${checks.length - failures}/${checks.length} static fixture URL guard checks passed; no imports, connections, or services.`);
process.exitCode = failures ? 1 : 0;
